{
  "rules": [
    {
      "category": "rent_increase_limit",
      "title": "Los Angeles Rent Stabilization Ordinance Annual Rent Increase Limit",
      "requirement": "Landlords of covered rental units may increase rent no more than once every 12 months, based on the annual percentage change in the regional Consumer Price Index as published by the Department, with a minimum increase of 3% and a maximum of 8%. An additional 1% may be added for each utility (gas or electric) if fully paid by the landlord, up to an additional 2%.",
      "requirement_es": "Los propietarios de unidades de alquiler cubiertas pueden aumentar el alquiler no más de una vez cada 12 meses, según el cambio porcentual anual en el Índice de Precios al Consumidor regional publicado por el Departamento, con un aumento mínimo del 3% y un máximo del 8%. Se puede agregar un 1% adicional por cada servicio público (gas o electricidad) pagado en su totalidad por el propietario, hasta un máximo del 2% adicional.",
      "key_value": {
        "label": "annual rent increase cap",
        "value": "CPI (min 3%, max 8%) + up to 2% for gas/electric"
      },
      "coverage_conditions": {
        "type": "AND",
        "clauses": [
          {
            "field": "certificate_of_occupancy_date",
            "operator": "<=",
            "value": "1978-10-01",
            "note": "Housing accommodations located in a structure for which the first Certificate of Occupancy was issued after October 1, 1978 are exempt"
          }
        ]
      },
      "exemptions": [
        {
          "description": "Single-family dwellings, except where two or more dwelling units are located on the same lot (not exempting duplexes or condominiums).",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "single_family"
              },
              {
                "field": "units",
                "operator": "==",
                "value": 1
              }
            ]
          }
        },
        {
          "description": "Transient hotels, motels, and rooming houses occupied as primary residence for 30 days or less.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Dwelling unit in a nonprofit stock cooperative occupied by a shareholder tenant.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "nonprofit"
              }
            ]
          }
        },
        {
          "description": "Hospitals, state licensed care facilities, convents, monasteries, extended medical care, asylums, fraternities/sororities, or school/university student housing.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Government owned/operated housing accommodations specifically exempted from municipal rent regulation by law (excluding Section 8 vouchers).",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "government"
              }
            ]
          }
        },
        {
          "description": "Certified luxury housing accommodations rented at or above specified thresholds on May 31, 1978.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Certified substantial renovation units where work was completed on or after September 1, 1980.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Affordable housing accommodations with recorded 55-year government regulatory agreements for households at or below 60% AMI.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Recreational vehicles not occupied continuously for nine or more months.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "tenancy_length_months",
                "operator": "<",
                "value": 9
              },
              {
                "field": "property_type",
                "operator": "==",
                "value": "other"
              }
            ]
          }
        },
        {
          "description": "Mobilehome parks first issued a permit to operate on or after February 10, 1986.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "mobile_home"
              }
            ]
          }
        }
      ],
      "effective_date": "1979-05-01",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Violations of any provision of this chapter may be raised as affirmative defenses in unlawful detainer proceedings.",
      "source_citation": "L.A. Mun. Code § 151.06(D), § 151.07(A)(6)",
      "quote": {
        "chunk": "c71",
        "start_words": "The annual rent increase adjustment shall be",
        "end_words": "adjustment at eight percent (8%)."
      },
      "confidence": 0.95
    },
    {
      "category": "security_deposit",
      "title": "Annual Interest on Security Deposits",
      "requirement": "Landlords holding a residential tenant's security deposit for at least one year must pay annual interest on the deposit, either at the rate established annually by the Rent Adjustment Commission or using actual interest earned from a separate account with bank statements provided. The accrued interest must be paid annually or monthly as a direct payment or rent credit.",
      "requirement_es": "Los propietarios que retengan el depósito de seguridad de un inquilino residencial durante al menos un año deben pagar un interés anual sobre el depósito, ya sea a la tasa establecida anualmente por la Comisión de Ajuste de Alquileres o según el interés real obtenido de una cuenta bancaria con los estados de cuenta correspondientes. El interés acumulado debe pagarse anual o mensualmente mediante pago directo o crédito al alquiler.",
      "key_value": {
        "label": "security deposit interest",
        "value": "RAC established rate or actual interest earned"
      },
      "coverage_conditions": {
        "type": "AND",
        "clauses": [
          {
            "field": "tenancy_length_months",
            "operator": ">=",
            "value": 12,
            "note": "deposits held for at least one year"
          }
        ]
      },
      "exemptions": [
        {
          "description": "Mobile home parks are not governed by the security deposit interest provisions.",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "mobile_home"
              }
            ]
          }
        }
      ],
      "effective_date": "1990-12-06",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "If the landlord fails to pay interest, the tenant may bring an action for recovery in court, including small claims court.",
      "source_citation": "L.A. Mun. Code § 151.06.02",
      "quote": {
        "chunk": "c51",
        "start_words": "A landlord who is subject to the",
        "end_words": "for his or her tenants as follows:"
      },
      "confidence": 0.95
    }
  ]
}
